// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address addr) public {
        // Ensure addr is not the zero address (the contract owner is address(0) initially)
        vm.assume(addr != address(0));
        // The contract owner is address(0) after deployment, so prank as owner
        vm.prank(address(0));
        c.setApprovedLogger(addr, true);
        bool result = c.approvedToLog(addr);
        assertTrue(result);
    }
}

